# Proxy profile: one POST to the proxy, which adds the FileMaker credentials itself.
curl -X POST 'https://proxy.example.com/filemaker' -H 'Content-Type: application/json' -H "Authorization: Bearer $FM_PROXY_API_KEY" --data-raw '{"action":"findRecords","profile":{"id":"profile-proxy","database":"Sales DB","serverUrl":"https://fm.example.com"},"payload":{"layout":"Contacts","body":{"query":[{"City":"Portland","Status":"==Active"},{"City":"Seattle","omit":"true"}],"sort":[{"fieldName":"Name","sortOrder":"ascend"}],"limit":25,"offset":26}}}'